import './cloud-sync.js';
import {TRACKS,PILOT_CHAIN,DIAGNOSTIC,recommendTrack,product,splitParts,factFamily,nextDayDelayMs,isIndependentEvidence,createBlankLearner} from './pilot-data.js';

const $=s=>document.querySelector(s);
const storageKey='mathlab-pilot-v1';
const memory={};
function readStore(){try{return JSON.parse(localStorage.getItem(storageKey))||{a:createBlankLearner(),b:createBlankLearner(),learner:'a'}}catch{return memory.data||{a:createBlankLearner(),b:createBlankLearner(),learner:'a'}}}
function saveLearner(id,data){data.updatedAt=new Date().toISOString();const all={...readStore(),[id]:data,learner};store=all;memory.data=all;try{localStorage.setItem(storageKey,JSON.stringify(all));if($('#saveStatus'))$('#saveStatus').textContent='Saved on this device'}catch{if($('#saveStatus'))$('#saveStatus').textContent='Storage is unavailable. Progress lasts until this page closes.'}}
function writeStore(){saveLearner(learner,state)}
let store=readStore();let learner=store.learner||'a';let state=store[learner]||createBlankLearner();let hintLevel=0;let attempts=0;let accidentalAvailable=false;let sessionMissionId=null;let diagnosticLocked=false;

function ensureState(){const legacy=state.session;state={...createBlankLearner(),...state,diagnostic:{...createBlankLearner().diagnostic,...state.diagnostic},missions:{...state.missions},evidence:{...createBlankLearner().evidence,...state.evidence},sessions:{...(state.sessions||{})},family:{help:'',explain:'',continue:'',...(state.family||{})}};if(legacy?.missionId&&!state.sessions[legacy.missionId])state.sessions[legacy.missionId]={attempts:legacy.attempts||0,hints:legacy.hints||0,accidentalAvailable:Boolean(legacy.accidentalAvailable)};delete state.session}
ensureState();

function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function setFeedback(text,type=''){const el=$('#feedback');el.textContent=text;el.className='feedback '+type}
function statusLabel(value){return ({unknown:'Not checked',learning:'Learning with support',independent:'Independent evidence',pending:'Temporarily passed · fresh check due'}[value]||value)}
function statusClass(value){return value==='independent'?'independent':value==='pending'?'pending':value==='learning'?'learning':''}
function missionDone(index){return Boolean(state.missions[PILOT_CHAIN.missions[index].id]?.complete)}
function unlocked(index){if(index===0)return true;if(index===4)return missionDone(3);return missionDone(index-1)}
function track(){return TRACKS[state.track||'explorer']}
function loadSession(missionId){sessionMissionId=missionId;if(!state.sessions[missionId]){state.sessions[missionId]={attempts:0,hints:0,accidentalAvailable:false};writeStore()}const saved=state.sessions[missionId];attempts=Number(saved.attempts)||0;hintLevel=Number(saved.hints)||0;accidentalAvailable=Boolean(saved.accidentalAvailable)}
function saveSession(){state.sessions[sessionMissionId]={attempts,hints:hintLevel,accidentalAvailable};writeStore()}
function recordAttempt(){attempts++;accidentalAvailable=true;saveSession()}
function lockActivity(){document.querySelectorAll('#activity button,#activity input,#activity select').forEach(el=>el.disabled=true)}
function markEvidence(targetState,dim,independent){const current=targetState.evidence[dim];if(independent){targetState.evidence[dim]='independent'}else if(current==='unknown'){targetState.evidence[dim]='learning'}}
function completeMissionFor(targetLearner,targetState,index,{dimensions=[],pending=false,preview=false}={}){
  const mission=PILOT_CHAIN.missions[index];
  const session={...(targetState.sessions?.[mission.id]||{attempts:0,hints:0})};
  targetState.missions[mission.id]={complete:!preview,preview,attempts:session.attempts,hints:session.hints,completedAt:new Date().toISOString(),track:targetState.track};
  for(const d of dimensions)markEvidence(targetState,d,isIndependentEvidence(session.attempts,session.hints)&&!preview);
  if(pending){targetState.retestDue=Date.now()+nextDayDelayMs();targetState.evidence.application='pending';targetState.evidence.explanation=targetState.evidence.explanation==='unknown'?'learning':targetState.evidence.explanation}
  if(!preview&&index<4)targetState.activeMission=index+1;
  delete targetState.sessions[mission.id];
  saveLearner(targetLearner,targetState);
  if(learner===targetLearner){state=readStore()[targetLearner]||targetState;ensureState();sessionMissionId=null;render()}
}
function scheduleComplete(index,options,delay){const targetLearner=learner,targetTrack=state.track,targetMission=PILOT_CHAIN.missions[index].id;lockActivity();setTimeout(()=>{const latest=readStore()[targetLearner];if(!latest||latest.track!==targetTrack||latest.activeMission!==index||!latest.sessions?.[targetMission])return;completeMissionFor(targetLearner,latest,index,options)},delay)}

function arraySvg(rows,cols,split=null){
  const size=Math.min(44,Math.floor(480/cols));const pad=34;const width=cols*size+pad*2;const height=rows*size+pad*2;let cells='';
  for(let r=0;r<rows;r++)for(let c=0;c<cols;c++){const cls=split!==null&&c>=split?'cell-b':'cell-a';cells+=`<rect class="${cls}" x="${pad+c*size}" y="${pad+r*size}" width="${size-3}" height="${size-3}" rx="5"/>`}
  const line=split!==null?`<line class="split-line" x1="${pad+split*size-1.5}" y1="${pad-8}" x2="${pad+split*size-1.5}" y2="${pad+rows*size+5}"/>`:'';
  return `<svg class="array-svg" role="img" aria-label="${rows} rows and ${cols} columns${split!==null?', split after '+split+' columns':''}" viewBox="0 0 ${width} ${height}"><defs><pattern id="stripe" width="8" height="8" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><rect width="8" height="8" fill="#f7df9e"/><line x1="0" y1="0" x2="0" y2="8" stroke="#c68733" stroke-width="3"/></pattern></defs>${cells}${line}<text class="array-label" x="${pad+cols*size/2}" y="18" text-anchor="middle">${cols} columns</text><text class="array-label" x="12" y="${pad+rows*size/2}" transform="rotate(-90 12 ${pad+rows*size/2})" text-anchor="middle">${rows} rows</text></svg>`
}
function continueButton(label='Continue') {return `<button class="primary" type="button" data-action="continue">${label}</button>`}
function hintButton(){return `<button class="secondary" type="button" data-action="hint">Give me one hint</button>`}
function accidentalButton(){return '<button class="secondary" type="button" data-action="accidental">Accidental tap?</button>'}
function hintHtml(text){return hintLevel?`<div class="hint-box">${esc(text)}</div>`:''}

function renderDiagnostic(){
  const d=state.diagnostic;if(d.index>=DIAGNOSTIC.length){const rec=recommendTrack(d.score);state.track=state.track||rec;$('#activity').innerHTML=`<div class="complete-card"><div class="big-check">✓</div><p class="eyebrow">STARTING DEPTH FOUND</p><h3>${TRACKS[state.track].label}</h3><p>${TRACKS[state.track].description}</p><p class="microcopy">This is a starting recommendation, not a grade-level diagnosis. A parent can change it at any time.</p>${continueButton('Build equal groups →')}</div>`;return}
  const q=DIAGNOSTIC[d.index];const progress=((d.index)/DIAGNOSTIC.length)*100;let input='';
  if(q.choices)input=`<div class="answer-grid">${q.choices.map((x,i)=>`<button type="button" class="choice" data-answer="${i}">${esc(x)}</button>`).join('')}</div>`;
  else input=`<form id="numberForm" class="answer-row"><input id="numberAnswer" inputmode="numeric" aria-label="Answer" required><button class="primary">Check</button></form>`;
  $('#activity').innerHTML=`<div class="diagnostic-progress" aria-label="Question ${d.index+1} of ${DIAGNOSTIC.length}"><span style="width:${progress}%"></span></div><p class="eyebrow">QUESTION ${d.index+1} OF ${DIAGNOSTIC.length}</p><h3>${esc(q.prompt)}</h3><p class="microcopy">No timer. If reading gets in the way, a grown-up may read the question aloud.</p>${input}`;
  $$answers();if($('#numberForm'))$('#numberForm').onsubmit=e=>{e.preventDefault();diagnosticAnswer(Number($('#numberAnswer').value))};
}
function diagnosticAnswer(value){if(diagnosticLocked)return;diagnosticLocked=true;lockActivity();const targetLearner=learner,targetState=state,d=targetState.diagnostic,q=DIAGNOSTIC[d.index],correct=Number(value)===Number(q.answer);d.answers.push({id:q.id,correct});if(correct)d.score++;setFeedback(correct?'That relationship is clear.':q.why,correct?'good':'try');d.index++;writeStore();const expectedIndex=d.index;setTimeout(()=>{diagnosticLocked=false;if(learner===targetLearner&&state===targetState&&state.diagnostic.index===expectedIndex){setFeedback('');render()}},450)}
function $$answers(){document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>diagnosticAnswer(Number(b.dataset.answer)))}

function renderEqualGroups(){const t=track(),total=product(t.rows,t.cols);$('#activity').innerHTML=`<p class="eyebrow">BUILD IT</p><h3>What does this array say?</h3><div class="array-wrap">${arraySvg(t.rows,t.cols)}</div><p class="prompt">Choose the sentence that matches the array.</p><div class="answer-grid"><button class="choice" data-equal="correct">${t.rows} equal groups of ${t.cols}</button><button class="choice" data-equal="wrong">${t.rows} + ${t.cols} counters</button><button class="choice" data-equal="wrong">${total} groups of ${t.rows}</button></div>${hintHtml(`Treat each row as one group. Count how many rows there are, then how many counters are in each row.`)}<div class="answer-row">${hintButton()} ${accidentalButton()}</div>`;document.querySelectorAll('[data-equal]').forEach(b=>b.onclick=()=>{recordAttempt();if(b.dataset.equal==='correct'){setFeedback(`${t.rows} rows × ${t.cols} in each row = ${total}.`,'good');scheduleComplete(1,{dimensions:['concept','procedure']},550)}else setFeedback('Look at one complete row. Is it one group, or is every counter a group?','try')})}

function renderSplit(){const t=track();let split=t.split;const draw=()=>{const p=splitParts(t.rows,t.cols,split);$('#arrayHost').innerHTML=arraySvg(t.rows,t.cols,split);$('#splitLabel').textContent=`Split after ${split} columns: ${split} + ${t.cols-split} = ${t.cols}`;$('#equationText').innerHTML=`${t.rows} × ${t.cols} = ${t.rows} × ${split} + ${t.rows} × ${t.cols-split} = ${p.left} + <input id="rightPart" inputmode="numeric" aria-label="Right part"> = <input id="wholeTotal" inputmode="numeric" aria-label="Whole total">`};
  $('#activity').innerHTML=`<p class="eyebrow">MOVE THE DIVIDER</p><h3>A split changes the view, not the total.</h3><div id="arrayHost" class="array-wrap"></div><div class="divider-control"><label for="divider"><strong id="splitLabel"></strong></label><input id="divider" type="range" min="1" max="${t.cols-1}" value="${split}"></div><div id="equationText" class="equation"></div><div class="answer-row"><button class="primary" data-action="checkSplit">Check both blanks</button>${hintButton()}${accidentalButton()}</div>${hintHtml(hintLevel===1?'Count the striped columns. The right part still has the same number of rows.':`Multiply ${t.rows} by the number of striped columns. Then add both parts.`)}`;draw();$('#divider').oninput=e=>{split=Number(e.target.value);draw()}}
function checkSplit(){recordAttempt();const t=track(),split=Number($('#divider').value),p=splitParts(t.rows,t.cols,split);const right=Number($('#rightPart').value),whole=Number($('#wholeTotal').value);if(right===p.right&&whole===p.total){setFeedback(`Yes. ${p.left} + ${p.right} is still ${p.total}. The divider did not add or remove any counters.`,'good');scheduleComplete(2,{dimensions:['concept','procedure','explanation']},650)}else setFeedback(`The striped part has ${t.rows} rows. Use rows × striped columns, then combine the two parts.`,'try')}

function renderFactFamily(){const t=track(),f=factFamily(t.rows,t.cols);$('#activity').innerHTML=`<p class="eyebrow">SAME ARRAY · FOUR FACTS</p><h3>Multiplication builds the total. Division takes it apart.</h3><div class="array-wrap">${arraySvg(t.rows,t.cols)}</div><form id="familyForm"><div class="equation">${t.rows} × ${t.cols} = <input id="fTotal" inputmode="numeric" aria-label="Product"></div><div class="equation" style="margin-top:9px">${f.multiply} ÷ ${t.rows} = <input id="fCols" inputmode="numeric" aria-label="Columns"></div><div class="equation" style="margin-top:9px">${f.multiply} ÷ ${t.cols} = <input id="fRows" inputmode="numeric" aria-label="Rows"></div><div class="answer-row"><button class="primary">Check the family</button>${hintButton()}${accidentalButton()}</div></form>${hintHtml('Use the same array each time. The total, rows, and columns do not change—only the question changes.')}`;$('#familyForm').onsubmit=e=>{e.preventDefault();recordAttempt();if(Number($('#fTotal').value)===f.multiply&&Number($('#fCols').value)===f.divideByRows&&Number($('#fRows').value)===f.divideByCols){setFeedback('All three equations describe the same array.','good');scheduleComplete(3,{dimensions:['procedure','explanation'],pending:true},650)}else setFeedback('Point to the rows, columns, and total on the array. Match each blank to the part being asked for.','try')}}

function renderFresh(){const due=state.retestDue||Date.now()+nextDayDelayMs(),ready=Date.now()>=due;if(!ready&&!state.previewFresh){const hours=Math.max(1,Math.ceil((due-Date.now())/3600000));$('#activity').innerHTML=`<div class="lock-card"><p class="eyebrow">FRESH CHECK</p><strong>Come back after some time has passed.</strong><p>A new problem is most useful when the previous picture is no longer in working memory. About ${hours} hours remain.</p><button class="secondary" data-action="previewFresh">Preview now for parent testing</button><p class="microcopy">Preview results will not count as delayed evidence. The later check uses different numbers.</p></div>`;return}const t=track(),problem=ready?t.transfer.fresh:t.transfer.preview,total=problem.total,groups=problem.groups,answer=total/groups;$('#activity').innerHTML=`<p class="eyebrow">${ready?'DELAYED CHECK · NEW NUMBERS':'PARENT PREVIEW · NOT RECORDED AS DELAYED EVIDENCE'}</p><h3>A garden has ${total} plants in ${groups} equal rows.</h3><p class="prompt">How many plants belong in each row?</p><form id="freshForm"><div class="answer-row"><input id="freshAnswer" inputmode="numeric" aria-label="Plants in each row" required><button class="primary">Check</button>${hintButton()}</div></form>${hintHtml('Use the relationship among total, number of equal groups, and amount in each group. Draw an array if that helps.')}<div id="explainFresh" hidden><p class="prompt">Which explanation proves the answer?</p><div class="answer-grid"><button class="choice" data-proof="correct">${groups} × ${answer} = ${total}, so ${total} ÷ ${groups} = ${answer}.</button><button class="choice" data-proof="wrong">${groups} + ${answer} = ${total}, so the rows are equal.</button><button class="choice" data-proof="wrong">The answer is smaller, so it must be correct.</button></div></div>`;let answerAccepted=false;$('#freshForm').onsubmit=e=>{e.preventDefault();recordAttempt();if(Number($('#freshAnswer').value)===answer){answerAccepted=true;setFeedback('The number fits. Now choose the explanation that proves it.','good');$('#explainFresh').hidden=false;$('#freshForm input').disabled=true;$('#freshForm button.primary').disabled=true}else setFeedback('Use total ÷ number of equal rows. You can also ask: what number multiplied by the rows gives the total?','try')};document.querySelectorAll('[data-proof]').forEach(b=>b.onclick=()=>{if(!answerAccepted)return;if(b.dataset.proof==='correct'){const preview=!ready;setFeedback(preview?'The preview works. Return after the delay to collect fresh evidence with different numbers.':'You transferred the relationship to a new problem and proved it.','good');scheduleComplete(4,{dimensions:['application','explanation'],preview},750)}else{recordAttempt();setFeedback('A proof must connect the number of rows, amount in each row, and the total.','try')}})}

function renderComplete(index){const m=PILOT_CHAIN.missions[index];$('#activity').innerHTML=`<div class="complete-card"><div class="big-check">✓</div><p class="eyebrow">MISSION COMPLETE</p><h3>${esc(m.title)}</h3><p>Your work is saved for this learner.</p>${index<4?continueButton('Continue to the next mission →'):'<a class="primary" href="./" style="display:inline-flex;text-decoration:none;align-items:center">Return to Math Labs</a>'}</div>`}
function renderMission(){const index=state.activeMission;const m=PILOT_CHAIN.missions[index];if(sessionMissionId!==m.id){loadSession(m.id);setFeedback('')};$('#missionEyebrow').textContent=`MISSION ${m.number} · ${m.kind.replace('-',' ').toUpperCase()}`;$('#missionTitle').textContent=m.title;$('#missionObjective').textContent=m.objective;$('#missionTime').textContent=`ABOUT ${m.minutes} MIN`;if(missionDone(index)){renderComplete(index);return}if(index>0&&!unlocked(index)){state.activeMission=Math.max(0,index-1);sessionMissionId=null;writeStore();render();return}if(index===0)renderDiagnostic();else if(index===1)renderEqualGroups();else if(index===2)renderSplit();else if(index===3)renderFactFamily();else renderFresh()}

function renderNav(){const active=state.activeMission;$('#missionNav').innerHTML=PILOT_CHAIN.missions.map((m,i)=>{const done=missionDone(i),lock=!unlocked(i);return `<button type="button" class="mission-button ${i===active?'active':''} ${lock?'locked':''}" data-mission="${i}" ${lock?'disabled':''}><span class="mission-number">${m.number}</span><span class="mission-label">${esc(m.title)}</span><span class="mission-state">${done?'✓':lock?'◌':'›'}</span></button>`}).join('');document.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>{state.activeMission=Number(b.dataset.mission);sessionMissionId=null;writeStore();render()})}
function renderTrack(){const t=track();$('#trackCard').innerHTML=`<strong>Current depth: ${t.label}</strong><span>${t.description}</span><select id="trackSelect" aria-label="Choose learning depth">${Object.values(TRACKS).map(x=>`<option value="${x.id}" ${x.id===t.id?'selected':''}>${x.label}</option>`).join('')}</select><small>Changing depth restarts the learning chain so evidence from different difficulty levels is never mixed.</small>`;$('#trackSelect').onchange=e=>{const next=e.target.value;if(next===state.track)return;const starting=state.missions['starting-point'];state.track=next;state.activeMission=starting?.complete?1:0;state.missions=starting?.complete?{'starting-point':starting}:{};state.evidence={concept:'unknown',procedure:'unknown',application:'unknown',explanation:'unknown'};state.retestDue=null;state.previewFresh=false;state.sessions={};sessionMissionId=null;writeStore();render()}}
function renderEvidence(){const labels={concept:'Concept',procedure:'Procedure',application:'Application',explanation:'Explain & transfer'};$('#evidenceGrid').innerHTML=Object.entries(labels).map(([k,label])=>`<div class="evidence-item"><header><span>${label}</span><span><i class="status-dot status-${statusClass(state.evidence[k])}"></i>${statusLabel(state.evidence[k])}</span></header><p>${k==='concept'?'Sees what the structure means.':k==='procedure'?'Uses the relationship accurately.':k==='application'?'Solves a changed situation independently.':'Explains why and detects errors.'}</p></div>`).join('')}
function renderFamily(){ensureState();$('#helpNote').value=state.family.help;$('#explainNote').value=state.family.explain;$('#continueNote').value=state.family.continue}
function render(){ensureState();$('#learnerSelect').value=learner;renderTrack();renderNav();renderEvidence();renderFamily();renderMission()}

document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='continue'){if(state.activeMission===0&&state.diagnostic.index>=DIAGNOSTIC.length){state.missions['starting-point']={complete:true,completedAt:new Date().toISOString(),score:state.diagnostic.score};state.activeMission=1;sessionMissionId=null;writeStore();render()}else{state.activeMission=Math.min(4,state.activeMission+1);sessionMissionId=null;writeStore();render()}}else if(a==='hint'){hintLevel++;accidentalAvailable=false;saveSession();renderMission()}else if(a==='accidental'){if(!accidentalAvailable){setFeedback('There is no recent tap to remove.','try');return}attempts=Math.max(0,attempts-1);accidentalAvailable=false;saveSession();setFeedback('That tap was removed from the attempt record.','good');renderMission()}else if(a==='checkSplit')checkSplit();else if(a==='previewFresh'){state.previewFresh=true;writeStore();render()}});
$('#learnerSelect').onchange=e=>{store={...readStore(),[learner]:state};learner=e.target.value;state=store[learner]||createBlankLearner();sessionMissionId=null;diagnosticLocked=false;ensureState();writeStore();render()};
for(const [id,key] of [['helpNote','help'],['explainNote','explain'],['continueNote','continue']])$('#'+id).addEventListener('input',e=>{state.family[key]=e.target.value;writeStore()});
$('#resetPilot').onclick=()=>{if(confirm(`Reset the pilot path for ${learner==='a'?'Ella':'Mila'}? This cannot be undone.`)){state=createBlankLearner();state.family={help:'',explain:'',continue:''};sessionMissionId=null;writeStore();render()}};
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('sw.js'));
render();
